 class ExtraPanel {public ulong handle; public PanelPlacement placement;public bool hidden;}
 static readonly Dictionary<int,ExtraPanel> extraPanels=new Dictionary<int,ExtraPanel>();
 static bool interaction;static bool capturesVisible=true;
 static object PanelsVisible(Dictionary<string,object> c){capturesVisible=Text(c,"enabled").ToLower()=="true";foreach(var p in extraPanels){if(!fixture){if(capturesVisible&&!p.Value.hidden)Check(OpenVR.Overlay.ShowOverlay(p.Value.handle));else Check(OpenVR.Overlay.HideOverlay(p.Value.handle));}Emit(new{type="panel-visibility",panelId=p.Key,visible=capturesVisible&&!p.Value.hidden});}return new{enabled=capturesVisible};}
 static PanelPlacement mainPlacement=DefaultPanel(0);
 static bool ValidAnchor(string s,bool dash){return s=="pinned"||s=="wrist-left"||s=="wrist-right"||s=="head"||(dash&&s=="dashboard");}
 static PanelPlacement DefaultPanel(int id){return new PanelPlacement{id=id};}
 static ulong ExtraHandle(int id){ExtraPanel p;return extraPanels.TryGetValue(id,out p)?p.handle:0;}
 static float[] Values(HmdMatrix34_t m){return new[]{m.m0,m.m1,m.m2,m.m3,m.m4,m.m5,m.m6,m.m7,m.m8,m.m9,m.m10,m.m11};}
 static HmdMatrix34_t Matrix(float[] a){if(a==null||a.Length!=12)throw new Exception("Invalid panel transform.");return new HmdMatrix34_t{m0=a[0],m1=a[1],m2=a[2],m3=a[3],m4=a[4],m5=a[5],m6=a[6],m7=a[7],m8=a[8],m9=a[9],m10=a[10],m11=a[11]};}
 static HmdMatrix34_t Multiply(HmdMatrix34_t a,HmdMatrix34_t b){var x=Values(a);var y=Values(b);var r=new float[12];for(int row=0;row<3;row++){for(int col=0;col<3;col++)for(int k=0;k<3;k++)r[row*4+col]+=x[row*4+k]*y[k*4+col];r[row*4+3]=x[row*4+3];for(int k=0;k<3;k++)r[row*4+3]+=x[row*4+k]*y[k*4+3];}return Matrix(r);}
 static HmdMatrix34_t Rotation(double yaw,double pitch){double a=yaw*Math.PI/180,b=pitch*Math.PI/180;return new HmdMatrix34_t{m0=(float)Math.Cos(a),m1=(float)(Math.Sin(a)*Math.Sin(b)),m2=(float)(Math.Sin(a)*Math.Cos(b)),m5=(float)Math.Cos(b),m6=(float)-Math.Sin(b),m8=(float)-Math.Sin(a),m9=(float)(Math.Cos(a)*Math.Sin(b)),m10=(float)(Math.Cos(a)*Math.Cos(b))};}
 static void Place(ulong handle,PanelPlacement p,bool recenter){if(fixture)return;var local=Rotation(p.yaw,p.pitch);local.m3=(float)p.x;local.m7=(float)p.y;local.m11=(float)p.z;
  if(p.anchor=="pinned") {if(recenter||p.basis==null){var poses=new TrackedDevicePose_t[OpenVR.k_unMaxTrackedDeviceCount];system.GetDeviceToAbsoluteTrackingPose(ETrackingUniverseOrigin.TrackingUniverseStanding,0,poses);if(!poses[0].bPoseIsValid)throw new Exception("Put on the headset, then place the panel again.");var b=poses[0].mDeviceToAbsoluteTracking;b.m3-=b.m2*1.4f;b.m7-=b.m6*1.4f;b.m11-=b.m10*1.4f;p.basis=Values(b);}var absolute=Multiply(Matrix(p.basis),local);Check(OpenVR.Overlay.SetOverlayTransformAbsolute(handle,ETrackingUniverseOrigin.TrackingUniverseStanding,ref absolute));}
  else {uint device=0;if(p.anchor.StartsWith("wrist")){device=system.GetTrackedDeviceIndexForControllerRole(p.anchor=="wrist-left"?ETrackedControllerRole.LeftHand:ETrackedControllerRole.RightHand);if(device==OpenVR.k_unTrackedDeviceIndexInvalid||!system.IsTrackedDeviceConnected(device))throw new Exception("That hand controller is not connected.");var wrist=Rotation(0,-70);wrist.m7=.08f;wrist.m11=-.12f;local=Multiply(wrist,local);}else local.m11-=.8f;Check(OpenVR.Overlay.SetOverlayTransformTrackedDeviceRelative(handle,device,ref local));}
  Check(OpenVR.Overlay.SetOverlayWidthInMeters(handle,(float)p.width));Check(OpenVR.Overlay.SetOverlayAlpha(handle,(float)p.alpha));Check(OpenVR.Overlay.SetOverlayCurvature(handle,(float)p.curve));Check(OpenVR.Overlay.SetOverlayFlag(handle,VROverlayFlags.MakeOverlaysInteractiveIfVisible,interaction));
 }
 static PanelPlacement ReadPlacement(Dictionary<string,object> c,int id,PanelPlacement old){var p=Json.Deserialize<PanelPlacement>(Json.Serialize(old??DefaultPanel(id)));string anchor=Text(c,"anchor");if(anchor!=""){if(!ValidAnchor(anchor,id==0))throw new Exception("Unknown panel anchor.");if(anchor!=p.anchor)p.basis=null;p.anchor=anchor;}p.width=Bound(c,"width",p.width,.18,3);p.alpha=Bound(c,"alpha",p.alpha,.15,1);p.curve=Bound(c,"curve",p.curve,0,1);p.x=Bound(c,"x",p.x,-3,3);p.y=Bound(c,"y",p.y,-3,3);p.z=Bound(c,"z",p.z,-3,3);p.yaw=Bound(c,"yaw",p.yaw,-180,180);p.pitch=Bound(c,"pitch",p.pitch,-180,180);return p;}
 static double Bound(Dictionary<string,object> c,string k,double fallback,double min,double max){return Math.Max(min,Math.Min(max,Number(c,k,fallback)));}
 static object PanelCommand(Dictionary<string,object> c){string type=Text(c,"type");int id=(int)Number(c,"panelId",0);if(type=="interaction"){interaction=Text(c,"enabled").ToLower()=="true";if(!fixture){if(watchHandle!=0)Check(OpenVR.Overlay.SetOverlayFlag(watchHandle,VROverlayFlags.MakeOverlaysInteractiveIfVisible,watchVisible));Check(OpenVR.Overlay.SetOverlayFlag(panel,VROverlayFlags.MakeOverlaysInteractiveIfVisible,interaction));foreach(var p in extraPanels)Check(OpenVR.Overlay.SetOverlayFlag(p.Value.handle,VROverlayFlags.MakeOverlaysInteractiveIfVisible,interaction));}return new{enabled=interaction};}if(type=="hud"||type=="hud-theme"){foreach(string key in new[]{"background","text","accent"}){string color=Text(c,key);if(System.Text.RegularExpressions.Regex.IsMatch(color,"^#[a-fA-F0-9]{6}$")){var value=System.Drawing.ColorTranslator.FromHtml(color);if(key=="background")hudBg=value;else if(key=="text")hudText=value;else hudAccent=value;}}if(type=="hud-theme")return new{updated=true};bool enabled=Text(c,"enabled").ToLower()=="true";string anchor=Text(c,"anchor");if(anchor!=""&&!ValidAnchor(anchor,false))throw new Exception("Choose a HUD anchor.");if(anchor.StartsWith("wrist")&&enabled){ShowWatch(anchor,watchWidth);if(!fixture&&hudHandle!=0)Check(OpenVR.Overlay.HideOverlay(hudHandle));hudEnabled=false;hudAnchor=anchor;return new{enabled=true,anchor=anchor,watch=true};}if(!enabled&&hudAnchor.StartsWith("wrist"))HideWatch();if(enabled&&!fixture){if(hudHandle==0)Check(OpenVR.Overlay.CreateOverlay("io.github.tkokero.orbit.experimental.hud","Orbit performance",ref hudHandle));var p=DefaultPanel(0);p.anchor=anchor==""?hudAnchor:anchor;p.width=p.anchor.StartsWith("wrist")?.26:.6;if(p.anchor=="head")p.y=-.25;else if(p.anchor=="pinned")p.y=-.35;Place(hudHandle,p,true);Check(OpenVR.Overlay.SetOverlayInputMethod(hudHandle,VROverlayInputMethod.None));Check(OpenVR.Overlay.SetOverlayFlag(hudHandle,VROverlayFlags.MakeOverlaysInteractiveIfVisible,false));Check(OpenVR.Overlay.ShowOverlay(hudHandle));}else if(!fixture&&hudHandle!=0)Check(OpenVR.Overlay.HideOverlay(hudHandle));hudEnabled=enabled;if(anchor!="")hudAnchor=anchor;return new{enabled=hudEnabled,anchor=hudAnchor};}
  if(type=="layout"){var list=new List<PanelPlacement>();list.Add(mainPlacement);foreach(var p in extraPanels)list.Add(p.Value.placement);return new{panels=list,universe=Universe(),hud=new{enabled=hudEnabled||watchEnabled,anchor=watchEnabled?watchAnchor:hudAnchor}};}
  if(id<0||id>4)throw new Exception("Panel limit is four capture panels.");
  if(type=="panel-manipulate")return GrabCommand(c);if(type=="panel-visible"){ExtraPanel p;if(!extraPanels.TryGetValue(id,out p))throw new Exception("Choose an open panel.");p.hidden=Text(c,"visible").ToLower()!="true";if(p.hidden&&focusedPanel==id)RestoreFocusedPanel();if(p.hidden&&grabPanel==id)EndGrab();if(!fixture){if(!p.hidden&&capturesVisible)Check(OpenVR.Overlay.ShowOverlay(p.handle));else Check(OpenVR.Overlay.HideOverlay(p.handle));}Emit(new{type="panel-visibility",panelId=id,visible=!p.hidden&&capturesVisible});return new{visible=!p.hidden};}if(type=="panel-close"){if(grabPanel==id)EndGrab();if(focusedPanel==id)RestoreFocusedPanel();ExtraPanel existing;if(id==0)throw new Exception("Use Close VR panel to stop Orbit.");if(extraPanels.TryGetValue(id,out existing)){if(!fixture){Check(OpenVR.Overlay.DestroyOverlay(existing.handle));ReleaseSurface(existing.handle);}extraPanels.Remove(id);}return new{closed=true};}
  if(type=="panel-create"){if(id==0||extraPanels.ContainsKey(id))throw new Exception("Choose an unused panel.");var p=ReadPlacement(c,id,null);ulong handle=0;if(!fixture){Check(OpenVR.Overlay.CreateOverlay("io.github.tkokero.orbit.experimental.capture."+id,"Orbit capture "+id,ref handle));try{Configure(handle);Place(handle,p,true);if(capturesVisible)Check(OpenVR.Overlay.ShowOverlay(handle));}catch{OpenVR.Overlay.DestroyOverlay(handle);throw;}}extraPanels.Add(id,new ExtraPanel{handle=handle,placement=p});return p;}
  PanelPlacement old=id==0?mainPlacement:extraPanels.ContainsKey(id)?extraPanels[id].placement:null;if(old==null)throw new Exception("This panel is closed.");var next=ReadPlacement(c,id,old);if(c.ContainsKey("basis")&&Text(c,"universe")==Universe()){var a=c["basis"] as System.Collections.IList;if(a!=null&&a.Count==12){var b=new float[12];for(int n=0;n<12;n++){b[n]=Convert.ToSingle(a[n]);if(float.IsNaN(b[n])||float.IsInfinity(b[n]))throw new Exception("Invalid placement.");}next.basis=b;}}
  bool recenter=Text(c,"recenter").ToLower()=="true";if(id==0&&next.anchor.StartsWith("wrist")){ShowWatch(next.anchor,watchWidth);next.width=watchWidth;if(!fixture)Check(OpenVR.Overlay.HideOverlay(panel));}else if(!fixture){if(next.anchor=="dashboard"){SetMode("dashboard");}else{Place(id==0?panel:ExtraHandle(id),next,recenter);Check(OpenVR.Overlay.ShowOverlay(id==0?panel:ExtraHandle(id)));}}if(id==0){mainPlacement=next;mode=next.anchor;Emit(new{type="mode",mode=mode,placement=mainPlacement});}else {extraPanels[id].placement=next;if(extraPanels[id].hidden&&!fixture)Check(OpenVR.Overlay.HideOverlay(ExtraHandle(id)));}return next;
 }
}
